gclM(){return"\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\u060c \u062f\u0627\u0645\u0646\u0647\u200c\u0647\u0627\u06cc \u0645\u062c\u0627\u0632 \u0648 \u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u0631\u0627 \u0628\u0631\u0627\u06cc \u0647\u0631 \u0648\u06cc\u062c\u062a \u0645\u062f\u06cc\u0631\u06cc\u062a \u06a9\u0646\u06cc\u062f."},
gclL(){return"\u0647\u0646\u0648\u0632 \u0648\u06cc\u062c\u06cc \u0646\u062f\u0627\u0631\u06cc\u062f. \u0628\u0627 \u062f\u06a9\u0645\u0647\u0654 \u0632\u06cc\u0631 \u06cc\u06a9 \u0648\u06cc\u062c\u062a \u0628\u0633\u0627\u0632\u06cc\u062f."},
gcly(){return"\u0648\u06cc\u062c\u062a \u062c\u062f\u06cc\u062f"},
gclF(){return"\u062d\u0630\u0641 \u062f\u0633\u062a\u0647\u200c\u062c\u0645\u0639\u06cc \u0645\u06a9\u0627\u0644\u0645\u0627\u062a"},
gclC(){return"\u0647\u0645\u0647\u0654 \u0645\u06a9\u0627\u0644\u0645\u0627\u062a \u0627\u06cc\u0646 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0648 \u062a\u0645\u0627\u0645 \u067e\u06cc\u0627\u0645\u200c\u0647\u0627 \u0628\u0631\u0627\u06cc \u0647\u0645\u06cc\u0634\u0647 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f. \u0627\u06cc\u0646 \u06a9\u0627\u0631 \u0628\u0631\u06af\u0634\u062a\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a. \u0627\u062f\u0627\u0645\u0647 \u0645\u06cc\u200c\u062f\u0647\u06cc\u062f\u061f"},
clD(a){return"\u0647\u0645\u0647\u0654 \u0645\u06a9\u0627\u0644\u0645\u0627\u062a \u0628\u0627 \u0648\u0636\u0639\u06cc\u062a \xab"+a+"\xbb \u0648 \u067e\u06cc\u0627\u0645\u200c\u0647\u0627\u06cc\u0634\u0627\u0646 \u0628\u0631\u0627\u06cc \u0647\u0645\u06cc\u0634\u0647 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f. \u0628\u0631\u06af\u0634\u062a\u200c\u0646\u0627\u067e\u0630\u06cc\u0631 \u0627\u0633\u062a. \u0627\u062f\u0627\u0645\u0647 \u0645\u06cc\u200c\u062f\u0647\u06cc\u062f\u061f"},
clE(a){return""+a+" \u0645\u06a9\u0627\u0644\u0645\u0647 \u062d\u0630\u0641 \u0634\u062f"},
gcn1(){return"\u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u06cc \u0686\u062a"},
gcmy(){return"\u067e\u06cc\u0648\u0633\u062a \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647: \u0628\u0633\u062a\u0647 (\u0627\u0628\u062a\u062f\u0627 \u062f\u0631 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM \u0631\u0648\u0634\u0646 \u0634\u0648\u062f)"},
gcmx(){return"\u067e\u06cc\u0648\u0633\u062a \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647: \u0645\u062c\u0627\u0632 \u2014 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631"},
gcmz(){return"\u067e\u06cc\u0648\u0633\u062a \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647: \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0628\u0633\u062a\u0647 \u0627\u0633\u062a"},
gcmZ(){return"\u0648\u0636\u0639\u06cc\u062a: \u0641\u0639\u0627\u0644 \u2014 \u062f\u0631 \u0633\u0627\u06cc\u062a \u062c\u0627\u0633\u0627\u0632\u06cc \u0645\u06cc\u200c\u0634\u0648\u062f"},
