gclI(){return"\u0645\u06a9\u0627\u0644\u0645\u0647 \u06cc\u0627\u0641\u062a \u0646\u0634\u062f \u2014 \u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u0631\u0627 \u0628\u0632\u0646\u06cc\u062f"},
gcmA(){return"\u0635\u0641\u062d\u0647\u0654 \u0641\u0639\u0644\u06cc \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647"},
