gcmB(){return"\u0631\u0627\u06cc\u0627\u0646\u0647"},
gcmE(){return"\u062f\u0633\u062a\u06af\u0627\u0647"},
cmS(a){return"\u0648\u06cc\u062c\u062a: "+a},
clA(a){return"\u0645\u0633\u0626\u0648\u0644: "+a},
gclQ(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u0645\u06a9\u0627\u0644\u0645\u0647"},
gcm6(){return"\u0644\u06cc\u062f\u0647\u0627"},
gbga(){return"\u067e\u0634\u062a\u06cc\u0628\u0627\u0646"},
gcmm(){return"\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647"},
gcm_(){return"\u0641\u0627\u06cc\u0644"},
gclB(){return"\u067e\u06cc\u0648\u0633\u062a \u0641\u0627\u06cc\u0644 (\u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631\u060c \u0628\u0633\u062a\u0631 crm_web_chat)"},
gcml(){return"\u067e\u0627\u0633\u062e\u2026 (Ctrl+Enter \u0627\u0631\u0633\u0627\u0644)"},
gbgb(){return"\u0627\u0631\u0633\u0627\u0644"},
gcmQ(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u0648\u06cc\u062c\u062a \u0686\u062a"},
gcmR(){return"\u0648\u06cc\u062c\u062a \u0686\u062a \u062c\u062f\u06cc\u062f"},
gcmP(){return"\u067e\u0633 \u0627\u0632 \u0627\u06cc\u062c\u0627\u062f\u060c \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0648 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u0627\u062a\u0635\u0627\u0644 API \u0627\u0632 \u0645\u0646\u0648\u06cc \u2026 \u0648\u06cc\u062c\u062a \u0642\u0627\u0628\u0644 \u06a9\u067e\u06cc \u0627\u0633\u062a. \u062f\u0627\u0645\u0646\u0647\u0654 \u0645\u062c\u0627\u0632 \u0641\u0642\u0637 \u0627\u0645\u0646\u06cc\u062a \u0645\u0631\u0648\u0631\u06af\u0631 (CORS) \u0627\u0633\u062a."},
gcmV(){return"\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a (\u062f\u0627\u062e\u0644\u06cc)"},
gcmU(){return"\u0645\u062b\u0627\u0644: \u0641\u0631\u0648\u0634\u06af\u0627\u0647 \u0627\u06cc\u0646\u062a\u0631\u0646\u062a\u06cc"},
gcmT(){return"\u0641\u0642\u0637 \u062f\u0631 \u067e\u0646\u0644 \u0634\u0645\u0627 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u062a\u0627 \u0628\u06cc\u0646 \u0686\u0646\u062f \u0648\u06cc\u062c\u062a \u062a\u0645\u0627\u06cc\u0632 \u0628\u06af\u0630\u0627\u0631\u06cc\u062f."},
gcmY(){return"\u062f\u0627\u0645\u0646\u0647\u200c\u0647\u0627\u06cc \u0645\u062c\u0627\u0632 \u062f\u0631\u062e\u0648\u0627\u0633\u062a"},
gcmX(){return"shop.ir\u060c blog.shop.ir"},
gcmW(){return"\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc. \u0641\u0642\u0637 \u0646\u0627\u0645 \u0645\u06cc\u0632\u0628\u0627\u0646 (\u0628\u062f\u0648\u0646 https://)\u061b \u062c\u062f\u0627 \u0628\u0627 \u0648\u06cc\u0631\u06af\u0648\u0644 \u0644\u0627\u062a\u06cc\u0646 \u06cc\u0627 \u0641\u0627\u0631\u0633\u06cc. \u0627\u06af\u0631 \u062e\u0627\u0644\u06cc \u0628\u06af\u0630\u0627\u0631\u06cc\u062f\u060c \u0645\u062d\u062f\u0648\u062f\u06cc\u062a \u062f\u0627\u0645\u0646\u0647 \u0628\u0627 \u0645\u0646\u0637\u0642 \u0633\u0631\u0648\u0631 \u0637\u0628\u0642 \u0645\u0633\u062a\u0646\u062f API \u0627\u0639\u0645\u0627\u0644 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u062c\u0627\u0633\u0627\u0632\u06cc \u0631\u0648\u06cc \u062f\u0627\u0645\u0646\u0647\u0654 \u0645\u0634\u062e\u0635\u060c \u062d\u062a\u0645\u0627\u064b \u0647\u0645\u0627\u0646 \u062f\u0627\u0645\u0646\u0647 \u0631\u0627 \u0627\u0636\u0627\u0641\u0647 \u06a9\u0646\u06cc\u062f."},
gcmH(){return"\u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u062a\u0648\u0633\u0637 \u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0633\u0627\u06cc\u062a"},
gcmG(){return"\u0648\u0627\u0628\u0633\u062a\u0647 \u0628\u0647 \u067e\u0644\u0646 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc. \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u06cc\u062f \u0641\u0642\u0637 \u0628\u0631\u0627\u06cc \u0627\u06cc\u0646 \u0648\u06cc\u062c\u062a \u0628\u0628\u0646\u062f\u06cc\u062f\u061b \u0627\u06af\u0631 \u0631\u0648\u0634\u0646 \u0628\u0645\u0627\u0646\u062f\u060c \u0645\u062b\u0644 \u0633\u0627\u06cc\u0631 \u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u0633\u062a."},
gcmF(){return"\u0627\u0644\u0627\u0646 \u062f\u0631 \u0633\u0637\u062d \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0627\u0633\u062a. \u0627\u0632 \u0645\u0633\u06cc\u0631 \xab\u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u2192 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a CRM\xbb (\u06cc\u0627 \u0645\u0646\u0648\u06cc \u0645\u0631\u0628\u0648\u0637) \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0631\u0633\u0627\u0644 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0686\u062a \u0648\u0628 \u0631\u0627 \u0631\u0648\u0634\u0646 \u06a9\u0646\u06cc\u062f\u060c \u0628\u0639\u062f \u0628\u0631\u06af\u0631\u062f\u06cc\u062f \u0648 \u0627\u06cc\u0646 \u0633\u0648\u06cc\u06cc\u0686 \u0631\u0627 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u0646\u06cc\u062f."},
gcmN(){return"\u0648\u06cc\u062c\u062a \u0641\u0639\u0627\u0644"},
gcmM(){return"\u0627\u06af\u0631 \u063a\u06cc\u0631\u0641\u0639\u0627\u0644 \u0634\u0648\u062f\u060c \u0628\u0627 \u0647\u0645\u06cc\u0646 \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0645\u06a9\u0627\u0644\u0645\u0647\u0654 \u062c\u062f\u06cc\u062f \u0634\u0631\u0648\u0639 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f (\u0648\u06cc\u062c\u062a\u200c\u0647\u0627\u06cc \u0642\u062f\u06cc\u0645 \u062f\u0631 \u067e\u0646\u0644 \u0628\u0627\u0642\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u0646\u062f)."},
gcme(){return"\u0644\u0637\u0641\u0627\u064b \xab\u0646\u0627\u0645 \u0648\u06cc\u062c\u062a\xbb \u0631\u0627 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f (\u0645\u062b\u0644\u0627\u064b \u0646\u0627\u0645 \u0633\u0627\u06cc\u062a \u06cc\u0627 \u0628\u062e\u0634)."},
gclK(){return"\u0627\u06cc\u062c\u0627\u062f"},
