gcmu(){return"\u0646\u0638\u0631\u0633\u0646\u062c\u06cc"},
gcmt(){return"\u0642\u0637\u0639"},
gcms(){return"\u0628\u062f\u0648\u0646 \u06a9\u0644\u06cc\u062f"},
