gcmw(){return"\u0627\u0631\u0633\u0627\u0644 \u0634\u062f"},
gcmv(){return"\u062e\u0648\u0627\u0646\u062f\u0647 \u0634\u062f"},
gclw(){return"\u067e\u06cc\u0627\u0645 \u0635\u0648\u062a\u06cc \u062f\u0631 \u0686\u062a \u0648\u0628"},
gclv(){return"\u067e\u06cc\u0627\u0645\u200c\u0647\u0627\u06cc \u0635\u0648\u062a\u06cc \u06a9\u0648\u062a\u0627\u0647 (\u0628\u0627\u0632\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u06cc\u0627 \u0627\u067e\u0631\u0627\u062a\u0648\u0631) \u0645\u0627\u0646\u0646\u062f \u0647\u0631 \u0641\u0627\u06cc\u0644 \u062f\u0631 \u0641\u0636\u0627\u06cc \u0630\u062e\u06cc\u0631\u0647\u200c\u0633\u0627\u0632\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062d\u0633\u0627\u0628 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f."},
